server.tool(
  "capture_reference",
  "Persist a pattern grabbed from any page via the grab bridge so it survives the browser tab — the keep step. Call this right after a designer selects an element and gives a note, while the GrabBridgeSelection payload is still in hand. It validates the payload, truncates html to 8000 chars (flagging html_truncated), rejects styles/state_styles maps over 200 properties and non-http(s) urls, and stores one JSON record per reference under ~/.raven/references. Every save gets a fresh ref_id, so grabbing the same element twice keeps both. It does not screenshot, does not extract design tokens, and does not map anything onto the user's token vocabulary — that is map_reference_to_tokens.",
  {
    url: z.string().min(1).describe("Full http(s) URL of the page the pattern was grabbed from. Non-http(s) schemes are rejected."),
    selector: z.string().min(1).describe("CSS selector of the grabbed element, from the GrabBridgeSelection."),
    styles: z.record(z.string()).describe("Computed styles exactly as captured. Rejected if over 200 properties."),
    owner: z.enum(["self", "third-party"]).describe("Whether the grabbed pattern comes from the user's own product or someone else's site."),
    tags: z.array(z.string()).describe("Lowercase topic tags for later filtering, e.g. ['hero', 'typography']. Normalized (trimmed, deduped) on save."),
    app: z.string().optional().describe("Human name of the source app, e.g. 'Linear'. Caller-supplied; searched by search_references."),
    html: z.string().optional().describe("outerHTML of the grabbed element. Truncated to 8000 chars on save; omit if you only need styles."),
    rect: z.object({ x: z.number(), y: z.number(), width: z.number(), height: z.number() }).optional().describe("Bounding rect of the grabbed element in page coordinates."),
    state_styles: z.record(z.record(z.string())).optional().describe("Per-state computed styles, e.g. { hover: {...} }. Each state map is capped at 200 properties."),
    note: z.string().optional().describe("The designer's own words about why they liked this pattern — the highest-weighted field in search.")
  },
  async function ({ url, selector, styles, owner, tags, app, html, rect, state_styles, note }) {
    var reference = await saveReference({ url: url, selector: selector, styles: styles, owner: owner, tags: tags, app: app, html: html, rect: rect, state_styles: state_styles, note: note });
    return { content: [{ type: "text" as const, text: JSON.stringify({ tool: "capture_reference", ref_id: reference.ref_id, host: reference.host, captured_at: reference.captured_at, reference: reference }, null, 2) }] };
  }
);
server.tool(
  "search_references",
  "Find patterns previously kept with capture_reference — use before rebuilding something a designer already grabbed, or to recall 'that hero from Linear' by note, app, tag, or selector. Filters on host, owner, and tags compose with AND; the free-text query matches case-insensitively against note, app, tags, and selector with an explainable score (a note hit outweighs a selector hit) and a per-result 'why' naming the matched fields. Ordering is deterministic: score desc, then captured_at desc, then ref_id asc. It returns stored JSON records only — never images or base64 — and corrupt records are skipped and named in skipped[] rather than failing the call. It does not rank by similarity to live code and does not fetch the source site.",
  {
    query: z.string().optional().describe("Free text matched against note, app, tags, and selector. Omit to list everything that passes the filters."),
    host: z.string().optional().describe("Only references grabbed from this host, e.g. 'linear.app'. Lowercased."),
    owner: z.enum(["self", "third-party"]).optional().describe("Only references from the user's own product or only from third-party sites."),
    tags: z.array(z.string()).optional().describe("Only references carrying ALL of these tags (AND, not OR).")
  },
  async function ({ query, host, owner, tags }) {
    var res = await searchReferences({ query: query, host: host, owner: owner, tags: tags });
    return { content: [{ type: "text" as const, text: JSON.stringify({ tool: "search_references", total: res.total, corpus_size: res.corpus_size, skipped: res.skipped, results: res.results }, null, 2) }] };
  }
);
server.tool(
  "map_reference_to_tokens",
  "Translate a captured pattern's raw computed styles (e.g. font-size: 64px, color: rgb(247,248,248)) onto the project's own design tokens, so generated code uses the user's type ramp and palette instead of pasted literals from someone else's site. Pure and deterministic — no model, no network. Colours compare by sRGB distance (exact at 0, near under 12); lengths normalize to px at root 16 (exact at 0, near under 2px); unitless numbers near within 1%; font families compare normalized first family. Ref tokens are resolved before comparison; broken chains become named gaps. % and viewport units, shadows, gradients, and other unmatchable classes become gaps with a stated reason — never a forced match — and are excluded from the coverage denominator. An empty tokens array is not an error: every property comes back as a gap with coverage.ratio 0. It does not invent tokens for gaps and does not write any code.",
  {
    captured: z.record(z.string()).describe("Computed styles to translate, e.g. the styles map from a stored reference. Keys are CSS property names, values as captured."),
    tokens: z.array(z.any()).describe("The project's flattened design tokens (FlattenedDesignToken: path, group, name, value, kind, cssVar, ref?). kind 'ref' tokens are resolved via ref before comparison. Pass [] to surface that the project has no token vocabulary."),
    properties: z.array(z.string()).optional().describe("Only map these CSS properties. Omit to attempt every captured property."),
    thresholds: z.object({ rgb: z.number().optional(), px: z.number().optional(), ratio: z.number().optional(), root: z.number().optional() }).optional().describe("Override the near-match thresholds: sRGB distance (default 12), px (default 2), relative ratio for unitless (default 0.01), and the rem/em root in px (default 16).")
  },
  async function ({ captured, tokens, properties, thresholds }) {
    var map = await mapReferenceToTokens(captured, tokens, { properties: properties, thresholds: thresholds });
    return { content: [{ type: "text" as const, text: JSON.stringify({ tool: "map_reference_to_tokens", coverage: map.coverage, ramps_used: map.ramps_used, bindings: map.bindings, gaps: map.gaps }, null, 2) }] };
  }
);
